from PIL import Image
import numpy as np
a=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
R,G,B=a[:,:,0],a[:,:,1],a[:,:,2]; mx=a.max(2);mn=a.min(2);sat=(mx-mn)/np.maximum(mx,1)
def spans(m,y):
 xs=np.flatnonzero(m[y])
 if not len(xs): return ''
 runs=[]; s=xs[0]; p=xs[0]
 for x in xs[1:]:
  if x>p+1: runs.append((s,p));s=x
  p=x
 runs.append((s,p))
 return ','.join(f'{s}-{e}' for s,e in runs if e-s>=1)
ms={'bright':mx>180,'metal':(sat<.16)&(mx>150),'red':(R>G+30)&(R>B+35)&(R>95),'orange':(R>G+14)&(G>B+10)&(sat>.22)&(R>95)}
for y in range(20,100):
 vals=[]
 for n,m in ms.items():
  s=spans(m,y)
  if s: vals.append(n+'='+s)
 if vals: print(f'{y:3d} '+' | '.join(vals))
PY"

